<?php
require __DIR__ . '/../functions.php'; global $config;
if (isset($_GET['logout'])) { unset($_SESSION['is_admin']); header('Location: index.php'); exit; }
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); if (($_POST['action'] ?? '') === 'login') { if (hash_equals($config['admin_user'], $_POST['username'] ?? '') && hash_equals($config['admin_password'], $_POST['password'] ?? '')) { $_SESSION['is_admin'] = true; header('Location: index.php'); exit; } $error = 'Invalid login.'; } if (is_admin() && ($_POST['action'] ?? '') === 'save') { $statement = db()->prepare('UPDATE products SET price = ?, stock = ?, active = ? WHERE id = ?'); $statement->execute([(float)$_POST['price'], (int)$_POST['stock'], isset($_POST['active']) ? 1 : 0, (int)$_POST['id']]); } }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin | Lissi</title><link rel="stylesheet" href="../style.css"></head><body><main class="section shell"><a class="brand" href="../index.php"><img src="../assets/logo.jpeg" alt="Lissi"><span>LISSI / ADMIN</span></a><?php if (!is_admin()): ?><h2>Store control</h2><?php if ($error): ?><div class="notice"><?= e($error) ?></div><?php endif; ?><form class="form" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="login"><label>Username<input name="username" required></label><label>Password<input name="password" type="password" required></label><button class="dark">Sign in</button></form><?php else: ?><p class="eyebrow">Store control <a href="?logout=1">Log out</a></p><h2>Inventory</h2><?php foreach (db()->query('SELECT * FROM products ORDER BY id DESC') as $product): ?><form class="line" method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= $product['id'] ?>"><div class="art" style="background:<?= e($product['image_color']) ?>"><strong><?= e($product['short_name']) ?></strong></div><div><b><?= e($product['name']) ?></b><span>Stock <input name="stock" type="number" min="0" value="<?= $product['stock'] ?>"> Price <input name="price" type="number" min="0" value="<?= $product['price'] ?>"></span></div><label>Active <input name="active" type="checkbox" <?= $product['active'] ? 'checked' : '' ?>></label><button class="dark">Save</button></form><?php endforeach; ?><?php endif; ?></main></body></html>
